#[cfg(test)]
mod tests {
    use std::{collections::HashSet, fs, path::Path};

    use super::*;

    #[test]
    fn villager_profession_catalog_is_complete_ordered_and_unique() {
        assert_eq!(VANILLA_VILLAGER_PROFESSIONS.len(), 15);
        let mut resources = HashSet::new();
        for (registry_id, entry) in VANILLA_VILLAGER_PROFESSIONS.iter().enumerate() {
            assert_eq!(entry.profession as usize, registry_id);
            assert!(resources.insert(entry.resource_id));
        }
    }

    #[test]
    fn villager_profession_catalog_preserves_registry_and_texture_ordinals() {
        assert_eq!(
            VillagerModelProfession::for_vanilla_registry_id(0),
            Some(VillagerModelProfession::None)
        );
        assert_eq!(
            VillagerModelProfession::for_vanilla_registry_id(14),
            Some(VillagerModelProfession::Weaponsmith)
        );
        assert_eq!(VillagerModelProfession::for_vanilla_registry_id(-1), None);
        assert_eq!(VillagerModelProfession::for_vanilla_registry_id(15), None);
        assert_eq!(
            VillagerModelProfession::for_resource_id("minecraft:mason"),
            Some(VillagerModelProfession::Mason)
        );
        assert_eq!(
            VillagerModelProfession::for_resource_id("minecraft:beekeeper"),
            None
        );
        assert_eq!(VillagerModelProfession::None.texture_index(), None);
        assert_eq!(VillagerModelProfession::Armorer.texture_index(), Some(0));
        assert_eq!(
            VillagerModelProfession::Weaponsmith.texture_index(),
            Some(13)
        );
    }

    #[test]
    fn production_sources_do_not_redeclare_villager_profession_facts() {
        fn visit(directory: &Path, violations: &mut Vec<String>) {
            for entry in fs::read_dir(directory).unwrap() {
                let path = entry.unwrap().path();
                if path.is_dir() {
                    visit(&path, violations);
                    continue;
                }
                if path.extension().and_then(|value| value.to_str()) != Some("rs") {
                    continue;
                }
                let display = path.to_string_lossy();
                if display.ends_with("/villager_professions.rs")
                    || display.ends_with("/tests.rs")
                    || display.contains("/tests/")
                {
                    continue;
                }
                let source = fs::read_to_string(&path).unwrap();
                if source.contains("enum VillagerModelProfession")
                    || source.contains("fn villager_profession_from_entry_id(")
                    || source.contains("fn villager_profession_from_vanilla_registry_id(")
                    || source.contains("fn villager_profession_texture_index(")
                    || source.contains("\"minecraft:armorer\" => Some(VillagerModelProfession::")
                {
                    violations.push(display.to_string());
                }
            }
        }
        let mut violations = Vec::new();
        visit(
            Path::new(env!("CARGO_MANIFEST_DIR")).parent().unwrap(),
            &mut violations,
        );
        assert!(
            violations.is_empty(),
            "parallel villager-profession catalog owners: {violations:?}"
        );
    }
}
